package com.pollhub.controller;
import com.pollhub.dto.*;import com.pollhub.security.*;import com.pollhub.service.AuthService;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.*;import org.springframework.http.MediaType;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.test.web.servlet.MockMvc;import java.time.LocalDateTime;import java.util.Set;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(AuthController.class) @AutoConfigureMockMvc(addFilters=false) class AuthControllerTest{@Autowired MockMvc mvc;@MockitoBean AuthService service;@MockitoBean JwtAuthenticationFilter filter;@MockitoBean CustomUserDetailsService details;@MockitoBean RestAuthenticationEntryPoint entry;
 @Test void registers()throws Exception{when(service.register(any())).thenReturn(new UserResponse(1L,"Ana","Anić","ana@test.rs",Set.of("ROLE_USER"),LocalDateTime.now()));mvc.perform(post("/api/auth/register").contentType(MediaType.APPLICATION_JSON).content("{\"firstName\":\"Ana\",\"lastName\":\"Anic\",\"email\":\"ana@test.rs\",\"password\":\"password\"}")).andExpect(status().isCreated()).andExpect(jsonPath("$.email").value("ana@test.rs"));}
 @Test void logsIn()throws Exception{when(service.login(any())).thenReturn(new AuthResponse("jwt","Bearer",1L,"Ana","Anić","ana@test.rs",Set.of("ROLE_USER")));mvc.perform(post("/login").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\"ana@test.rs\",\"password\":\"password\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.token").value("jwt"));}}
